import{_ as a,o as r,c as o,a0 as t}from"./chunks/framework.D2qex3w9.js";const p=JSON.parse('{"title":"Order Status Badge Specification","description":"","frontmatter":{},"headers":[],"relativePath":"specs/order-status-badge/spec.md","filePath":"specs/order-status-badge/spec.md"}'),i={name:"specs/order-status-badge/spec.md"};function s(n,e,d,c,l,u){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="order-status-badge-specification" tabindex="-1">Order Status Badge Specification <a class="header-anchor" href="#order-status-badge-specification" aria-label="Permalink to &quot;Order Status Badge Specification&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Visual chip/badge component that renders auction order status values as colored indicators in the table, replacing plain text for quick scanability.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><h3 id="requirement-status-badge-rendering" tabindex="-1">Requirement: Status Badge Rendering <a class="header-anchor" href="#requirement-status-badge-rendering" aria-label="Permalink to &quot;Requirement: Status Badge Rendering&quot;">​</a></h3><p>The <code>generic-table-without-actions</code> component MUST render the status column value as a visual badge/chip element instead of plain text.</p><h4 id="scenario-status-renders-as-chip" tabindex="-1">Scenario: Status renders as chip <a class="header-anchor" href="#scenario-status-renders-as-chip" aria-label="Permalink to &quot;Scenario: Status renders as chip&quot;">​</a></h4><ul><li>GIVEN the table displays order rows with a <code>status</code> column</li><li>THEN each status cell renders as a small rounded chip with a background color</li></ul><h3 id="requirement-status-color-mapping" tabindex="-1">Requirement: Status Color Mapping <a class="header-anchor" href="#requirement-status-color-mapping" aria-label="Permalink to &quot;Requirement: Status Color Mapping&quot;">​</a></h3><p>The badge color MUST vary by status value using only CSS variables from <code>styles.scss</code>:</p><table tabindex="0"><thead><tr><th>Status</th><th>Color</th><th>CSS Variable</th></tr></thead><tbody><tr><td>en proceso</td><td>Amber/green</td><td><code>--card-color: #7ab400</code></td></tr><tr><td>aprobada</td><td>Green</td><td><code>--color-principal: #62A730</code></td></tr><tr><td>rechazada</td><td>Red</td><td><code>--color-rojo: #f83a40</code></td></tr></tbody></table><h4 id="scenario-en-proceso-renders-amber-chip" tabindex="-1">Scenario: &quot;en proceso&quot; renders amber chip <a class="header-anchor" href="#scenario-en-proceso-renders-amber-chip" aria-label="Permalink to &quot;Scenario: &quot;en proceso&quot; renders amber chip&quot;">​</a></h4><ul><li>GIVEN a row with <code>status = &quot;en proceso&quot;</code></li><li>WHEN the table renders</li><li>THEN the status cell shows an amber-colored badge using <code>var(--card-color)</code></li></ul><h4 id="scenario-aprobada-renders-green-chip" tabindex="-1">Scenario: &quot;aprobada&quot; renders green chip <a class="header-anchor" href="#scenario-aprobada-renders-green-chip" aria-label="Permalink to &quot;Scenario: &quot;aprobada&quot; renders green chip&quot;">​</a></h4><ul><li>GIVEN a row with <code>status = &quot;aprobada&quot;</code></li><li>WHEN the table renders</li><li>THEN the status cell shows a green-colored badge using <code>var(--color-principal)</code></li></ul><h4 id="scenario-rechazada-renders-red-chip" tabindex="-1">Scenario: &quot;rechazada&quot; renders red chip <a class="header-anchor" href="#scenario-rechazada-renders-red-chip" aria-label="Permalink to &quot;Scenario: &quot;rechazada&quot; renders red chip&quot;">​</a></h4><ul><li>GIVEN a row with <code>status = &quot;rechazada&quot;</code></li><li>WHEN the table renders</li><li>THEN the status cell shows a red-colored badge using <code>var(--color-rojo)</code></li></ul><h3 id="requirement-no-hardcoded-colors" tabindex="-1">Requirement: No Hardcoded Colors <a class="header-anchor" href="#requirement-no-hardcoded-colors" aria-label="Permalink to &quot;Requirement: No Hardcoded Colors&quot;">​</a></h3><p>All status badge colors MUST reference CSS variables from <code>styles.scss</code>. Hardcoded color values MUST NOT be used.</p><h4 id="scenario-css-variable-compliance" tabindex="-1">Scenario: CSS variable compliance <a class="header-anchor" href="#scenario-css-variable-compliance" aria-label="Permalink to &quot;Scenario: CSS variable compliance&quot;">​</a></h4><ul><li>GIVEN any status badge is rendered</li><li>THEN its background color uses <code>var(--card-color)</code>, <code>var(--color-principal)</code>, or <code>var(--color-rojo)</code></li><li>AND no hardcoded hex or RGB values are present</li></ul><h3 id="requirement-dynamic-class-binding" tabindex="-1">Requirement: Dynamic Class Binding <a class="header-anchor" href="#requirement-dynamic-class-binding" aria-label="Permalink to &quot;Requirement: Dynamic Class Binding&quot;">​</a></h3><p>The badge class MUST be dynamically bound to the row&#39;s status value using <code>[ngClass]</code> or equivalent Angular template binding.</p><h4 id="scenario-unknown-status-fallback" tabindex="-1">Scenario: Unknown status fallback <a class="header-anchor" href="#scenario-unknown-status-fallback" aria-label="Permalink to &quot;Scenario: Unknown status fallback&quot;">​</a></h4><ul><li>GIVEN a row with an unrecognized status value</li><li>WHEN the table renders</li><li>THEN the status cell renders with a neutral/default style</li><li>AND no error or exception is thrown</li></ul>',25)])])}const b=a(i,[["render",s]]);export{p as __pageData,b as default};
